from pathlib import Path
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak, KeepTogether
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib import colors
from pypdf import PdfReader
import pypdfium2 as pdfium
out=Path('output/pdf/CLEAR_Weekly_Agent_Checklist.pdf')
out.parent.mkdir(parents=True,exist_ok=True)
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='TitleC',fontName='Helvetica-Bold',fontSize=22,leading=27,textColor=colors.HexColor('#18334B'),spaceAfter=12))
styles.add(ParagraphStyle(name='HeadC',fontName='Helvetica-Bold',fontSize=12,leading=16,textColor=colors.HexColor('#007F79'),spaceBefore=10,spaceAfter=7))
styles.add(ParagraphStyle(name='BodyC',fontName='Helvetica',fontSize=10,leading=14,spaceAfter=8,textColor=colors.HexColor('#18334B')))
styles.add(ParagraphStyle(name='SmallC',fontName='Helvetica',fontSize=8.5,leading=12,spaceAfter=7,textColor=colors.HexColor('#52616D')))
story=[]
def add(text,style='BodyC'): story.append(Paragraph(text,styles[style]))
def task(code,title,action,done):
    story.append(KeepTogether([Paragraph(f'[ ] <b>{code} - {title}</b>',styles['HeadC']),Paragraph(action,styles['BodyC']),Paragraph('<b>Done when:</b> '+done,styles['SmallC'])]))
def footer(c,d):
    c.setFont('Helvetica',8);c.setFillColor(colors.HexColor('#52616D'))
    c.drawString(44,27,'CLEAR | Working checklist | Updated 13 November 2026')
    c.drawRightString(551,27,f'{d.page} / 3')
add('Agent checklist: next sessions','TitleC')
add('UPDATED 13 NOVEMBER 2026 | NEXT SESSION: 14 NOVEMBER','SmallC')
add('The seven stages below follow the original plan. Preprocessing is now complete according to the teammate. Mariana will pull the changes tomorrow; compatibility with the agents has not yet been checked.')
add('What was done today','HeadC')
add('[x] Explained both defense conclusions for case 1 and the orchestrator flow.<br/>[x] Added three orchestrator failure tests and simple English comments.<br/>[x] The full suite passed 25 tests before preparing the new cases.<br/>[x] Prepared two new JSON case drafts only. They have NOT been run, tested or added to the live runner.')
add('1. Understand and run the flow - completed for current code','HeadC')
add('Mariana understands the independent reports and the stop-on-error behaviour. Revisit only the parts affected by the incoming preprocessing changes. The assistant implements and explains changes; comments stay in simple English.','SmallC')
add('2. Cases and criteria - two new drafts to review','HeadC')
add('<b>04_documented_payment.json:</b> a 1,200 USD transfer with fictional agreement and invoice excerpts that state the purpose, account pair and due date. Defense should use the documents, but must not claim verified authenticity, innocence or a confirmed false positive.')
add('<b>05_empty_evidence.json:</b> no transaction, timestamp, score or alert flag. The proposed outcome is rejection before any model call. This differs from case 03, which still contains model output and a timestamp.')
add('[ ] Read and approve the scenarios and criteria.<br/>[ ] Explicitly connect the documents in case 04 to CaseContext; the current builder does not load these additional records.<br/>[ ] Add an offline rejection check for case 05 after agreeing the expected behaviour.<br/>[ ] Keep evaluation text and explanatory notes out of model evidence.')
add('Both files are in agents/reference_cases/. They are preparation material, not ready-to-run additions. CASE_NAMES and the experiment runner still use the original three cases. Do not interpret the earlier 25 passing tests as validation of the new drafts.','SmallC')
add('3. Prosecution / 4. Defense - development baseline completed','HeadC')
add('Two final Opus sets met the criteria on the original three cases in the assistant assessment. Preserve these outputs. Wider performance, new cases and independent human assessment remain to be checked.','SmallC')
add('5. Orchestrator - main failure checks completed','HeadC')
add('[x] Prosecution failure stops before defense.<br/>[x] Defense failure returns no combined result.<br/>[x] Final validation rejects an invented reference from either role.<br/>[ ] Recheck affected paths after integration changes. Define any new result status before changing the current stop-on-error policy.')
story.append(PageBreak())
add('Tomorrow: inspect the new delivery','TitleC')
add('SATURDAY, 14 NOVEMBER | REVIEW FIRST, THEN DECIDE','SmallC')
task('1','Protect local work, then pull','Before Mariana pulls, inspect git status and preserve local edits, especially the existing prompts.py changes. Keep a deliberate commit or backup; do not discard edits or resolve conflicts blindly. Mariana performs the pull.','The incoming changes are available and local work has not been lost. The assistant has not pulled them in advance.')
task('2','Review the two new cases together','Read case 04 and its fictional documents, then case 05 and the expected rejection. Explain what each case is meant to check.','Mariana understands the difference between documented purpose, verified legitimacy and no evidence at all.')
task('3','Inspect the preprocessing changes - stage 6','Review the actual changed files, README and generated schemas. Compare the new delivery with agents/service.py and case_context.py before changing the agent code. Do not assume the old interface still works.','We can name the changed files and explain which changes affect the agents.')
task('4','Write a concrete integration map','Check row_id, feature/metadata locations, account fields, timestamps and timezone, amounts/currencies, missing values, scorer compatibility and daily scoring inputs. Confirm how related_transactions is supplied and whether history coverage is known.','Every required agent input has a source or an explicit gap. Existing modelling agreements are reused where they still apply.')
add('Tomorrow ends with a small implementation plan','HeadC')
add('Choose the smallest required adapter changes, where they belong and how they will be checked. Identify missing artifacts or interface questions for the teammate. A completed preprocessing task is not yet evidence of a successful end-to-end agent review.')
add('<b>No immediate need to regenerate the 39 old outputs.</b> First understand the new data and the two draft cases. Only run checks relevant to the changes we choose to implement.','SmallC')
add('Files to open','HeadC')
add('agents/reference_cases/04_documented_payment.json<br/>agents/reference_cases/05_empty_evidence.json<br/>agents/service.py<br/>agents/case_context.py<br/>The preprocessing files actually changed by the pull','SmallC')
story.append(PageBreak())
add('Following sessions: integrate, then debate','TitleC')
add('Session 2 - target 15 November, or next available day','HeadC')
add('<b>Stage 6: implement the agreed integration changes.</b><br/>[ ] Adapt only fields or paths that changed; keep responsibilities separated.<br/>[ ] Ensure labels and ground-truth-derived fields are excluded from agent evidence.<br/>[ ] Verify row IDs, whole-day scoring and scorer/feature compatibility.<br/>[ ] Check the context for a real prepared row with a simulated text generator first.<br/>[ ] Add document evidence support for case 04 explicitly and keep case 05 as an offline rejection scenario.<br/>[ ] Run relevant offline checks, then the full suite after code changes.')
add('<b>Done when:</b> the new delivery produces the expected context, references remain traceable, and offline checks pass. If artifacts are missing, record the gap and continue with work that does not depend on them.','SmallC')
add('Session 3 - target 16 November, after integration checks','HeadC')
add('<b>Finish stage 6 and prepare the larger evaluation.</b><br/>[ ] Select a valid prepared row that is actually flagged and review its evidence.<br/>[ ] Run one controlled live end-to-end review when the offline handoff is sound.<br/>[ ] Compare claims with the source data and record failures or missing history.<br/>[ ] Evaluate the documented-purpose case only after its documents reach the agents.<br/>[ ] Plan at least ten identified cases for the later live evaluation, including the original three. Keep unseen examples for a meaningful check.')
add('Case 05 cannot count as a successful live report case: it is designed to be rejected before the API. Do not add an invented flag to force it through.','SmallC')
add('7. Debate and final delivery - after the foundations hold','HeadC')
add('[ ] Add one defense reply to specific prosecution arguments.<br/>[ ] Preserve the original facts and references; earlier arguments are not evidence.<br/>[ ] Return initial reports and reply with clear labels and a one-round limit.<br/>[ ] Test success, failure and call limits offline.<br/>[ ] Assess at least ten live-review cases in two series; compare the added value of the reply.<br/>[ ] Record model/code version, support for claims, failures, latency and usage when available.<br/>[ ] Write short reproduction instructions and obtain human assessment.')
add('The order is dependency-based, not a deadline to rush. Independent reports can continue to be evaluated while debate is being designed. Do not mark integration or debate complete just because preprocessing is finished.','SmallC')
add('When to test and where to resume','HeadC')
add('No tests or model calls were run while creating the two new drafts. After future case wiring or code changes, run focused checks and then the full suite. Reading JSON files needs no API call.<br/><font face="Courier" size="8">.\\.venv\\Scripts\\python.exe -B -m unittest discover -s agents/tests -v</font>','SmallC')
add('Current outputs and explanation: output/output/. Earlier outputs: archive_experiences/ inside that folder. Runner: agents/reference_cases/run_agent_iteration.py. Its --help option makes no API calls.','SmallC')
add('<b>Next session starts with:</b> preserve local work, pull the teammate changes, review the two case drafts and inspect the new preprocessing interface. Update this checklist with actual results before the following session.')
SimpleDocTemplate(str(out),pagesize=(595.28,841.89),leftMargin=44,rightMargin=44,topMargin=36,bottomMargin=45,title='CLEAR - Agent checklist and preprocessing integration plan',author='CLEAR project').build(story,onFirstPage=footer,onLaterPages=footer)
r=PdfReader(out)
assert len(r.pages)==3, len(r.pages)
render=pdfium.PdfDocument(str(out))
for i,page in enumerate(render):
    page.render(scale=1.2).to_pil().save(f'tmp/pdfs/next_sessions_{i+1}.png')
print(str(out.resolve()), 'pages:',len(r.pages))
